svg.script:
(function () {
  var svg = document.documentElement;
  var dark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;

  var colors = dark ? {
    neutral:  { fill: '#2a2a28', stroke: '#c3c2b7', width: 1.5 },
    active:   { fill: '#3a2317', stroke: '#ef7a63', width: 2.5 },
    agent:    { fill: '#241c35', stroke: '#9b7ee0', width: 2.5 },
    delivered:{ fill: '#142a42', stroke: '#3987e5', width: 2.5 }
  } : {
    neutral:  { fill: '#f2f1ee', stroke: '#52514e', width: 1.5 },
    active:   { fill: '#fdece3', stroke: '#d6563f', width: 2.5 },
    agent:    { fill: '#f1ecfb', stroke: '#6b46c1', width: 2.5 },
    delivered:{ fill: '#e7f0fb', stroke: '#2a78d6', width: 2.5 }
  };

  function paint(el, c) {
    el.style.fill = c.fill;
    el.style.stroke = c.stroke;
    el.style.strokeWidth = c.width;
  }

  var steps = [
    { cap1: 'Runde 1 -- Start', cap2: 'Hauptsitzung im Leerlauf, Agent arbeitet im Hintergrund',
      leerlauf: true, turnaktiv: false, agent: true, notif: 'hidden', connector: false, pull: false },
    { cap1: 'Runde 1 -- Turn beginnt', cap2: 'Nutzer schickt eine Nachricht, die Hauptsitzung wird aktiv',
      leerlauf: false, turnaktiv: true, agent: true, notif: 'hidden', connector: false, pull: false },
    { cap1: 'Runde 1 -- Agent wird fertig', cap2: 'Completion-Notification erscheint, wartet grau',
      leerlauf: false, turnaktiv: true, agent: false, notif: 'waiting', connector: false, pull: false },
    { cap1: 'Runde 1 -- Zustellung', cap2: 'Notification fließt sofort in den laufenden Turn',
      leerlauf: false, turnaktiv: true, agent: false, notif: 'delivered', connector: true, pull: false },
    { cap1: 'Runde 2 -- Start', cap2: 'Hauptsitzung wieder im Leerlauf, Agent arbeitet erneut im Hintergrund',
      leerlauf: true, turnaktiv: false, agent: true, notif: 'hidden', connector: false, pull: false },
    { cap1: 'Runde 2 -- Agent wird fertig', cap2: 'Hauptsitzung ist noch im Leerlauf -- Notification wartet grau, nichts passiert von selbst',
      leerlauf: true, turnaktiv: false, agent: false, notif: 'waiting', connector: false, pull: true },
    { cap1: 'Runde 2 -- Wartezeit', cap2: 'könnte Sekunden oder Stunden dauern -- nichts startet von selbst einen neuen Turn',
      leerlauf: true, turnaktiv: false, agent: false, notif: 'waiting', connector: false, pull: true },
    { cap1: 'Runde 2 -- Turn beginnt', cap2: 'und nimmt die wartende Notification gleich mit -- kein zusätzlicher Schritt nötig',
      leerlauf: false, turnaktiv: true, agent: false, notif: 'delivered', connector: true, pull: false }
  ];

  var step = 1;
  var leerlaufBox = document.getElementById('leerlaufBox');
  var turnAktivBox = document.getElementById('turnAktivBox');
  var agentBox = document.getElementById('agentBox');
  var notificationBox = document.getElementById('notificationBox');
  var connectorGroup = document.getElementById('connectorGroup');
  var pullGroup = document.getElementById('pullGroup');
  var capLine1 = document.getElementById('capLine1');
  var capLine2 = document.getElementById('capLine2');
  var stepIndicator = document.getElementById('stepIndicator');

  function render() {
    var s = steps[step - 1];
    paint(leerlaufBox, s.leerlauf ? colors.active : colors.neutral);
    paint(turnAktivBox, s.turnaktiv ? colors.active : colors.neutral);
    paint(agentBox, s.agent ? colors.agent : colors.neutral);

    if (s.notif === 'hidden') {
      notificationBox.style.opacity = '0';
    } else if (s.notif === 'waiting') {
      notificationBox.style.opacity = '1';
      paint(notificationBox, colors.neutral);
    } else if (s.notif === 'delivered') {
      notificationBox.style.opacity = '1';
      paint(notificationBox, colors.delivered);
    }

    connectorGroup.style.opacity = s.connector ? '1' : '0';
    pullGroup.style.opacity = s.pull ? '1' : '0';
    capLine1.textContent = s.cap1;
    capLine2.textContent = s.cap2;
    stepIndicator.textContent = step + ' / ' + steps.length;
  }

  function next() { step = (step >= steps.length) ? 1 : step + 1; render(); }
  function prev() { step = (step <= 1) ? steps.length : step - 1; render(); }

  document.getElementById('nextBtn').addEventListener('click', next);
  document.getElementById('prevBtn').addEventListener('click', prev);
  document.getElementById('bgClick').addEventListener('click', next);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight' || e.key === ' ') { next(); e.preventDefault(); }
    if (e.key === 'ArrowLeft') { prev(); e.preventDefault(); }
  });

  render();
})();
